PORTAL.levels.forEach(level => { level.tasks = level.tasks.map(([domain,code,title,skills]) => ({id:`L${level.id}-${code}`,domain,code,title,skills,level:level.id,ref:`${level.section} ${code}`,pages:level.pages})); });
